"use server";

import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function placeOrder(userId: string) {
  return prisma.$transaction(async (tx) => {
    const order = await tx.order.create({ data: { userId, status: "PENDING" } });
    const intent = await stripe.paymentIntents.create({ amount: 1000, currency: "usd" });
    return tx.order.update({ where: { id: order.id }, data: { paymentIntentId: intent.id } });
  });
}

